def transform(grid):
    from collections import Counter
    H, W = len(grid), len(grid[0])
    cnt = Counter(v for row in grid for v in row)
    bg = cnt.most_common(1)[0][0]
    nonbg = [c for c in cnt if c != bg]
    if not nonbg:
        return [row[:] for row in grid]
    bycount = sorted(nonbg, key=lambda c: cnt[c])
    special = bycount[0]
    marker = bycount[-1]
    out = [row[:] for row in grid]
    mcells = [(r, c) for r in range(H) for c in range(W) if grid[r][c] == marker]
    scells = [(r, c) for r in range(H) for c in range(W) if grid[r][c] == special]
    if not scells or not mcells:
        return out
    mrows = sorted(set(r for r, c in mcells))
    if len(mrows) <= 2:
        sr, sc = scells[0]
        info = {mr: sorted(set(c for (r, c) in mcells if r == mr)) for mr in mrows}
        if len(mrows) == 2:
            r1, r2 = mrows
            if sc in info[r1]:
                al, fa = r1, r2
            elif sc in info[r2]:
                al, fa = r2, r1
            else:
                al = min(mrows, key=lambda mr: min(abs(sc - c) for c in info[mr]))
                fa = r2 if al == r1 else r1
            out[sr][sc] = 4
            step = 1 if al > sr else -1
            r = sr + step
            while r != al:
                if 0 <= r < H and grid[r][sc] == bg:
                    out[r][sc] = special
                r += step
            acols = info[al]
            if sc in acols:
                idx = acols.index(sc)
            else:
                idx = 0 if sc < acols[0] else len(acols) - 1
            fcols = info[fa]
            fc = fcols[min(idx, len(fcols) - 1)]
            top, bot = min(al, fa), max(al, fa)
            for r in range(top, bot):
                if grid[r][fc] == bg:
                    out[r][fc] = special
                elif grid[r][fc] == special:
                    out[r][fc] = 4
            return out
        else:
            mr = mrows[0]
            cols = info[mr]
            cx = max(cols, key=lambda x: abs(x - sc))
            out[sr][sc] = 4
            step = 1 if mr > sr else -1
            r = sr + step
            while r != mr:
                if 0 <= r < H and grid[r][cx] == bg:
                    out[r][cx] = special
                r += step
            return out
    blocks = []
    start = prev = mrows[0]
    for r in mrows[1:]:
        if r == prev + 1:
            prev = r
        else:
            blocks.append((start, prev)); start = prev = r
    blocks.append((start, prev))
    if len(blocks) != 2:
        return out
    bcols = [sorted(set(c for (r, c) in mcells if b0 <= r <= b1)) for (b0, b1) in blocks]
    sblock = None
    for i, (b0, b1) in enumerate(blocks):
        if any(b0 <= r <= b1 for (r, c) in scells):
            sblock = i
    if sblock is None:
        return out
    oblock = 1 - sblock
    s0, s1 = blocks[sblock]
    o0, o1 = blocks[oblock]
    scol = bcols[sblock][0] if len(bcols[sblock]) == 1 else None
    ocol = bcols[oblock][0] if len(bcols[oblock]) == 1 else None
    if scol is None or ocol is None:
        return out
    for (r, c) in scells:
        if s0 <= r <= s1:
            out[r][c] = 4
            step = 1 if c > ocol else (-1 if c < ocol else 0)
            cc = c + step
            while 0 <= cc < W and grid[r][cc] != marker:
                if grid[r][cc] == bg:
                    out[r][cc] = special
                elif grid[r][cc] == special:
                    out[r][cc] = 4
                cc += step
            tr = o0 + (r - s0)
            if o0 <= tr <= o1 and tr < H:
                lo, hi = min(scol, ocol), max(scol, ocol)
                if lo < hi:
                    rng = range(lo, hi)
                elif lo == 0:
                    rng = range(lo + 1, W - 1)
                else:
                    rng = range(1, lo)
                for cc in rng:
                    if grid[tr][cc] == bg:
                        out[tr][cc] = special
                    elif grid[tr][cc] == special:
                        out[tr][cc] = 4
    return out
